const leads = $input.all().map(i => i.json);
const flat = leads.length === 1 && Array.isArray(leads[0]) ? leads[0] : leads;
const now = Date.now();

const sequences = [];

for (const lead of flat) {
  if (!lead.company || lead.stage === 'Closed Won / Client') continue;
  if (!lead.decision_maker || !lead.decision_maker.includes('@')) continue;

  const daysSince = (now - new Date(lead.last_activity).getTime()) / 86400000;
  const notes = lead.notes || '';

  if (lead.stage === 'Outreach Sent' && daysSince >= 3 && daysSince < 5 && !notes.includes('Day 3 follow-up')) {
    sequences.push({ json: { ...lead, sequenceDay: 3, subject: `Quick follow-up — ${lead.company}`, body: `Hi,\n\nI sent a note earlier this week about operational efficiency at ${lead.company}.\n\nManufacturers in ${lead.industry || 'your industry'} typically lose $180K–$320K annually to the friction patterns I identified.\n\nHappy to share a brief analysis — no strings attached. Worth 15 minutes?\n\nBest,\nHUNTER Intelligence` } });
  }

  if ((lead.stage === 'Outreach Sent' || lead.stage === 'Diagnostic Ready') && daysSince >= 7 && daysSince < 9 && !notes.includes('Day 7 follow-up')) {
    sequences.push({ json: { ...lead, sequenceDay: 7, subject: `How a ${lead.industry || 'manufacturing'} shop cut reporting time by 90%`, body: `Hi,\n\nQuick story: a shop similar to ${lead.company} was spending 15 hours/week on production reports from 12 spreadsheets.\n\nWe built a live KPI dashboard in 3 weeks. Any metric in under 30 seconds now.\n\nIf ${lead.company} has similar challenges, I can run a free diagnostic. 15 minutes this week?\n\nBest,\nHUNTER Intelligence` } });
  }

  if ((lead.stage === 'Outreach Sent' || lead.stage === 'Diagnostic Ready') && daysSince >= 14 && daysSince < 16 && !notes.includes('Day 14 breakup')) {
    sequences.push({ json: { ...lead, sequenceDay: 14, subject: `Closing the loop — ${lead.company}`, body: `Hi,\n\nI've reached out a few times about operational intelligence for ${lead.company}. Totally understand if timing isn't right.\n\nI'll close your file for now. If things change, reply "DIAGNOSTIC" and I'll run a free friction report — no call required.\n\nBest,\nHUNTER Intelligence` } });
  }
}

if (sequences.length === 0) return [{ json: { _empty: true, message: 'No follow-ups due today' } }];
return sequences;

